function binary_search(a, target) {
    let left = 0;
    let right = a.length - 1;
    while (left <= right) {
        const mid = Math.floor((left + right) / 2);
        if (a[mid] === target) {
            return mid;
        } else if (a[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return -1;
}

int binary_search(std::vector<int>& a, int target) {
    int left = 0;
    int right = a.size() - 1;
    while (left <= right) {
        int mid = (right + left) / 2;
        if (a[mid] == target) {
            return mid;
        } else if (a[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return -1;
}
